import json
s=[('cobalt',[0,1,2,3,4],1320,360),('reed',[0,2,4],1380,180),('plum',[1,3,5],30,150),('shell',[6],1350,90),('gold',[0],0,90),('elm',[5],60,180)]
jobs=[(1,29),(1,30),(1,150),(1,179),(1,180),(5,59),(5,60),(5,149),(5,150),(5,180),(6,1349),(6,1350),(0,0),(0,89),(0,90),(2,359),(2,360),(4,1380)]
def receiver(d,m,fault=None):
    covers=[]
    for i,(name,days,a,b) in enumerate(s):
        duration=(b-a)%1440
        owner=d if a<b or m>=a else (d-1)%7
        clock=a<=m<b if a<b else m>=a or m<b
        if clock and (d if fault=='day_owner' else owner) in days:
            covers.append((duration,i,name))
    if not covers:return 'idle'
    return min(covers,key=(lambda x:x[1]) if fault=='first_match' else (lambda x:(x[0],x[1])))[2]
def oracle(d,m):
    t=d*1440+m
    choices=[]
    for i,(name,days,a,b) in enumerate(s):
        duration=b-a if b>a else 1440-a+b
        for day in days:
            for week in [-1,0,1]:
                start=(day+7*week)*1440+a
                if start<=t<start+duration:choices.append((duration,i,name))
    return min(choices)[2] if choices else 'idle'
w={'day_owner':{'job':{'receiver':{'day':5,'minute':180}},'expected':'cobalt'},'first_match':{'job':{'receiver':{'day':1,'minute':30}},'expected':'plum'}}
obj={'routes':[receiver(d,m) for d,m in jobs],'witnesses':w}
payload=json.dumps(obj,separators=(',',':'))
decoded=json.loads(payload)
assert set(decoded)=={'routes','witnesses'}
assert decoded['routes']==[oracle(d,m) for d,m in jobs]
assert set(decoded['witnesses'])=={'day_owner','first_match'}
for fault,witness in decoded['witnesses'].items():
    assert set(witness)=={'job','expected'} and set(witness['job'])=={'receiver'}
    r=witness['job']['receiver']; assert set(r)=={'day','minute'}
    d,m=r['day'],r['minute']
    assert type(d) is int and type(m) is int and 0<=d<=6 and 0<=m<1440
    expected=witness['expected']
    assert oracle(d,m)==receiver(d,m)==expected
    assert receiver(d,m,fault)!=expected
    other='first_match' if fault=='day_owner' else 'day_owner'
    assert receiver(d,m,other)==expected
